'use strict';
/* Extended learning surfaces share the original progress store. No secrets or model calls in this client. */
state.study = {concepts:{},artifacts:{},debug:{},speaking:{},capstones:{},decision:{},...state.study};
const study=state.study;
const ui={concept:0,search:'',category:'All',protocol:'mcp',phase:0,buildTab:'milestones',milestone:0,file:0,codeSearch:'',debug:0,debugRevealed:false,strategy:0,interviewMode:'concept',interviewItem:0,speakingTab:'30',capstone:0,timerSeconds:120,timerRunning:false};
let codeManifest=null,codeLoadError='',codeLoading=false,timerHandle=null;
ui.blueprintModes={seo:'trace',leads:'trace',news:'trace'};
ui.blueprintNodes={seo:0,leads:0,news:0};
const textValue=v=>typeof v==='string'?v:Array.isArray(v)?v.join('\n'):JSON.stringify(v,null,2);
const paragraph=v=>String(textValue(v)||'').split('\n\n').filter(Boolean).map(t=>`<p>${esc(t)}</p>`).join('');
const sourceLinks=s=>(s||[]).length?`<div class="source-list">${s.map(x=>ext(x.url,x.title)).join('')}</div>`:'';
const sourceOne=s=>s?sourceLinks(Array.isArray(s)?s:[s]):'';
const selectOptions=(arr,value)=>arr.map(x=>`<option value="${esc(x)}" ${x===value?'selected':''}>${esc(x)}</option>`).join('');
function storedConcept(c){return study.concepts[c.id]||{level:'unread',evidence:''}}
function newLink(h,title,sub){return `<a href="#${h}"><b>${title}</b>${sub}</a>`}
const originalStart=renderStart;
const originalBlueprint=renderBlueprint;
renderBlueprint=function(id){
 const b=BLUEPRINTS[id],d=USECASE_DEPTH[id],mode=ui.blueprintModes[id];
 const tabs=`<div class="tabs">${[['trace','Trace the workflow'],['steps','8 build steps'],['contracts','Data, tools & evaluation']].map(([k,t])=>`<button class="tab ${mode===k?'active':''}" data-blueprint-mode="${k}">${t}</button>`).join('')}</div>`;
 if(mode==='steps')return originalBlueprint(id).replace('<div class="build-inputs">',tabs+'<div class="build-inputs">');
 const intro=pageIntro('APPLICATION BLUEPRINT',esc(b.title),esc(b.subtitle))+tabs;
 if(mode==='contracts')return intro+`<div class="paper panel"><div class="code-head"><h3>The record that holds the workflow together</h3><button class="button small" id="copyWorkflowSchema">Copy schema example</button></div><p>Fictional fixture. Preserve identities, provenance, versions, state transitions, and outcome events so the system can recover and learn.</p><pre>${esc(textValue(d.schema))}</pre></div><div class="section-head"><h2>Tool contracts, not vague capabilities.</h2></div><div class="paper panel table-scroll"><table><thead><tr><th>Tool</th><th>Input</th><th>Output</th><th>Permission / boundary</th></tr></thead><tbody>${d.tools.map(t=>`<tr><td><code>${esc(t.name)}</code></td><td>${esc(textValue(t.inputs))}</td><td>${esc(textValue(t.output))}</td><td>${esc(textValue(t.permission))}</td></tr>`).join('')}</tbody></table></div><div class="section-head"><h2>Evaluate the behavior you need.</h2></div><div class="paper panel table-scroll"><table><thead><tr><th>Case</th><th>Expected behavior</th><th>Measure</th></tr></thead><tbody>${d.evals.map(e=>`<tr><td>${esc(e.case)}</td><td>${esc(e.expected)}</td><td>${esc(e.measure)}</td></tr>`).join('')}</tbody></table></div><div class="twocol" style="margin-top:22px"><div class="paper panel"><h3>Deploy the smallest useful version</h3>${paragraph(d.deployment)}</div><div class="paper panel"><h3>Repeat across customers</h3>${paragraph(d.repeatable)}</div></div><div class="callout mint"><span class="hand">Capture the outcome</span>${esc(d.metric)}</div>${sourceLinks(d.sources)}`;
 return intro+`<div class="live-note">PROPOSED APPLICATION DESIGN · Fictional SignalDesk example · The downloadable lab implements the retrieval/API/MCP building block; additional domain integrations below are explicit build work.</div><div class="paper diagram"><div class="diagram-head"><span class="hand">Follow one task from intake to outcome</span><small>CLICK A STAGE · 01 → 06</small></div><div class="flow usecase-flow">${d.nodes.map((n,i)=>`<button class="node ${['yellow','blue','lilac','peach','mint','blue'][i]} ${ui.blueprintNodes[id]===i?'selected':''}" data-usecase-node="${i}" aria-pressed="${ui.blueprintNodes[id]===i}"><strong>${esc(n.title)}</strong><small>${esc(n.actor)}</small></button>`).join('')}</div>${harness()}</div><div id="usecaseDetail">${usecaseDetail(id)}</div><div class="twocol"><div class="paper panel"><h3>What carries across customers?</h3>${paragraph(d.repeatable)}</div><div class="paper panel"><h3>What counts as a useful result?</h3>${paragraph(d.metric)}</div></div><div class="callout yellow"><span class="hand">Explain this system in two minutes</span>Choose one record. Name its source of truth, the next model decision, the tool that executes it, the check that gates progress, and the event that establishes success. Then explain what changes for a second customer.</div>${sourceLinks(d.sources)}`;
};
function usecaseDetail(id){const n=USECASE_DEPTH[id].nodes[ui.blueprintNodes[id]];return `<article class="paper concept-main" style="margin:22px 0"><div class="eyebrow">${esc(n.actor)}</div><h2>${esc(n.title)}</h2><div class="twocol"><div><div class="label-sm">Input / current state</div>${paragraph(n.input)}</div><div><div class="label-sm">Output / next state</div>${paragraph(n.output)}</div></div><div class="label-sm">What happens</div>${paragraph(n.operation)}<div class="step-output"><strong>JUDGMENT VS RULES</strong><p>${esc(n.rule)}</p></div><div class="misconception"><b>Failure to anticipate</b><br>${esc(n.failure)}</div></article>`}
renderStart=function(){const h=originalStart();const block=`<div class="section-head"><h2>The new mastery workbench.</h2><span class="edition-tag">WORKING CODE + EXPLANATIONS</span></div><div class="workbench">${newLink('concepts','Understand','45 concepts, examples & misconceptions')}${newLink('protocol','Trace','Follow API and MCP requests end to end')}${newLink('build','Build','Run the same capability through both paths')}${newLink('debug','Diagnose','12 failures, traces & regression checks')}${newLink('strategy','Connect','Your interview notes, turned into systems')}${newLink('interview','Explain','Practice a clear, defensible answer')}</div>`;return h.replace('<div class="section-head"><h2>One system.',block+'<div class="section-head"><h2>One system.');};

function conceptsPage(){const c=DEEP_CONCEPTS[ui.concept],p=storedConcept(c);const categories=['All',...new Set(DEEP_CONCEPTS.map(x=>x.category))];return `${pageIntro('THE LANGUAGE OF AGENTS','Know the term. Explain the mechanism.','Definitions are the starting point. For each concept, connect it to a real component, a tradeoff, a failure mode, and an explanation you can give aloud.')}<div class="section-metadata"><span>${DEEP_CONCEPTS.length} concepts</span><span>Searchable · source-linked · saved learning notes</span><a href="#interview">Practice explaining one →</a></div><div class="course-layout"><aside><div class="search-box"><input id="conceptSearch" type="search" placeholder="Search API, MCP, memory…" aria-label="Search concepts" value="${esc(ui.search)}"></div><select class="compact-select" id="conceptCategory" aria-label="Concept category">${selectOptions(categories,ui.category)}</select><div class="tiny muted" id="conceptCount"></div><div class="directory" id="conceptDirectory"></div></aside><article class="paper concept-main"><div class="concept-header"><div><div class="eyebrow">${esc(c.category)}</div><h2>${esc(c.term)}</h2></div><button class="button small" id="conceptSpeak">Explain this aloud ↗</button></div><p class="definition">${esc(c.plain)}</p><div class="label-sm">Under the hood</div>${paragraph(c.technical)}<div class="twocol"><div><div class="label-sm">A concrete example</div>${paragraph(c.example)}</div><div><div class="label-sm">Where it lives</div>${paragraph(c.where)}</div></div><div class="label-sm">When to use it</div>${paragraph(c.when)}<div class="misconception"><b>Watch for this misconception</b><br>${esc(c.misconception)}</div><div class="knowledge-check"><div class="label-sm no-margin">Check your understanding</div><p>${esc(c.question)}</p><details><summary>Show the reasoning</summary>${paragraph(c.answer)}</details></div><div class="concept-status"><label class="field">Your learning stage<select id="conceptLevel">${[['unread','Not studied yet'],['read','Read the explanation'],['explain','Can explain in my own words'],['applied','Applied in a working example']].map(([k,t])=>`<option value="${k}" ${p.level===k?'selected':''}>${t}</option>`).join('')}</select><small>Self-reported. Application needs an artifact you can show.</small></label><label class="field">Your example or evidence<textarea id="conceptEvidence" placeholder="Describe a run, code change, test, or explanation you can demonstrate.">${esc(p.evidence)}</textarea></label></div>${sourceLinks(c.sources)}</article></div><div class="section-head"><h2>The distinctions interviewers probe.</h2></div><div class="paper panel decision-table"><table><thead><tr><th>Distinction</th><th>How to explain it</th><th>Decision it informs</th></tr></thead><tbody><tr><td>API / SDK / MCP / tool call</td><td>An API exposes a capability; an SDK helps call it; MCP standardizes interaction with capabilities; a model tool call proposes an action the application executes.</td><td>Direct integration or reusable MCP adapter? Which boundary owns credentials and validation?</td></tr><tr><td>Workflow / agent / harness</td><td>A workflow defines steps in code. An agent chooses next steps from observations. The harness implements execution, state, policy, budgets, and recovery.</td><td>Where does adaptive judgment justify its cost?</td></tr><tr><td>RAG / fine-tuning</td><td>RAG supplies retrieved evidence at inference time. Fine-tuning changes model parameters through training.</td><td>Do you need fresh facts and provenance, learned behavior, or both?</td></tr><tr><td>Context / memory / state</td><td>Context is the current model input. Memory retains selected information across calls. Operational state records what the workflow has done and may do next.</td><td>What must survive a restart, permission change, or context reset?</td></tr></tbody></table></div>`}
function paintConceptDirectory(){const query=ui.search.toLowerCase();const matches=DEEP_CONCEPTS.map((c,i)=>({c,i})).filter(({c})=>(ui.category==='All'||c.category===ui.category)&&[c.term,c.plain,c.technical,c.example].join(' ').toLowerCase().includes(query));$('#conceptCount').textContent=`${matches.length} matching concepts`;$('#conceptDirectory').innerHTML=matches.map(({c,i})=>`<button data-concept="${i}" class="${i===ui.concept?'active':''}" aria-pressed="${i===ui.concept}">${esc(c.term)}<small>${storedConcept(c).level==='unread'?'':'•'}</small></button>`).join('')||'<div class="empty-state">No match. Try a broader term.</div>';document.querySelectorAll('[data-concept]').forEach(b=>b.onclick=()=>{ui.concept=Number(b.dataset.concept);render()})}

function protocolPage(){const steps=PROTOCOL_LAB[ui.protocol],s=steps[ui.phase],v=PROTOCOL_VERSION_INFO;const lane=ui.protocol==='mcp'?[['Host + model','Own the task & policy','yellow'],['MCP client','Discover and call','blue'],['MCP server','Expose the capability','lilac'],['HTTP API','Validate and retrieve','mint']]:[['Host + model','Own the task & policy','yellow'],['API adapter','Construct the request','blue'],['HTTP API','Validate and retrieve','mint']];return `${pageIntro('APIS & MCP, UNFOLDED','Follow the request. Find the boundaries.','The same research capability, accessed directly or through MCP. Watch who discovers, decides, validates, executes, and returns evidence.')}<div class="tabs"><button class="tab ${ui.protocol==='direct'?'active':''}" data-protocol="direct">Direct API integration</button><button class="tab ${ui.protocol==='mcp'?'active':''}" data-protocol="mcp">MCP integration</button><a class="button small" href="#build">Open the runnable version ↗</a></div><div class="protocol-version"><b>Version matters:</b> this lab uses MCP ${esc(v.specification)} and ${esc(v.sdk)}. The current discovery flow and the older initialization handshake are labeled separately below. Wire messages are representative excerpts; runnable integration tests exercise the actual SDK.</div><div class="paper protocol-board"><div class="diagram-head"><span class="hand">One capability. Two integration paths.</span><small>READ THE BOUNDARIES ↓</small></div><div class="protocol-lane">${lane.map(x=>`<div class="protocol-box ${x[2]}"><b>${x[0]}</b><small>${x[1]}</small></div>`).join('')}</div><div class="trust-boundary"><span>Model sees tool descriptions and results.</span><span>Trusted application code owns permissions.</span><span>Credentials stay outside model context.</span></div><div class="loop-control">Tool result → host → next model turn → another allowed action or a final answer. The host enforces the stop condition, even if the model asks to continue.</div></div><div class="phase-list">${steps.map((x,i)=>`<button data-phase="${i}" class="${i===ui.phase?'active':''}" aria-label="Protocol step ${i+1}: ${esc(x.title)}">${i+1}</button>`).join('')}</div><article class="paper panel protocol-step"><span class="actor">${esc(s.actor)}</span><h2>${esc(s.title)}</h2><p>${esc(s.detail)}</p><div class="schema-grid"><div><div class="label-sm">Request / input</div><pre>${esc(textValue(s.request))}</pre></div><div><div class="label-sm">Response / output</div><pre>${esc(textValue(s.response))}</pre></div></div><div class="callout yellow"><b>Boundary to explain:</b> ${esc(s.boundary)}</div><div class="protocol-controls"><button class="button" id="phasePrev" ${ui.phase===0?'disabled':''}>← Previous</button><span class="protocol-counter">Step ${ui.phase+1} of ${steps.length}</span><button class="button primary" id="phaseNext" ${ui.phase===steps.length-1?'disabled':''}>Next message →</button></div></article><div class="section-head"><h2>Go deeper into the contract.</h2></div>${MCP_DETAILS.map(x=>`<details class="details"><summary>${esc(x.title)}</summary><div>${paragraph(x.text)}${x.code?`<pre>${esc(textValue(x.code))}</pre>`:''}${sourceOne(x.source)}</div></details>`).join('')}<div class="paper panel decision-table"><h3>Choose the integration for the requirement.</h3><table><thead><tr><th>Question</th><th>Direct API</th><th>MCP adapter</th></tr></thead><tbody><tr><td>One known service and one application?</td><td>Often a smaller surface to implement and debug.</td><td>Useful if you also need compatible host reuse or standard capability discovery.</td></tr><tr><td>Multiple compatible AI applications need the capability?</td><td>Each application may need custom adaptation.</td><td>A reusable server exposes the capability through a shared protocol.</td></tr><tr><td>Does it remove authorization work?</td><td>No. The API enforces its contract and permissions.</td><td>No. Host policy, server authorization, and downstream API access still matter.</td></tr><tr><td>Where is the business logic?</td><td>In the underlying service and application.</td><td>The server can wrap the same service; avoid duplicating inconsistent business rules.</td></tr></tbody></table></div><div class="callout mint"><span class="hand">Say this in the interview</span>“I would use MCP when a reusable capability needs to work across compatible agent applications. For a single integration, a direct API may be simpler. In either design, I still need a clear tool contract, authorization, error handling, and evaluations.”</div>${sourceLinks(v.sources)}`}

function milestoneBody(){const m=BUILD_MILESTONES[ui.milestone];return `<div class="course-layout"><div class="directory">${BUILD_MILESTONES.map((x,i)=>`<button data-milestone="${i}" class="${i===ui.milestone?'active':''}"><span>${String(i+1).padStart(2,'0')} · ${esc(x.title)}</span><small>${study.artifacts[x.id]?.trim()?'◉':''}</small></button>`).join('')}</div><article class="paper concept-main"><div class="eyebrow">MILESTONE ${ui.milestone+1} OF 10</div><h2>${esc(m.title)}</h2><p class="definition">${esc(m.action)}</p><div class="step-output"><strong>ARTIFACT TO PRODUCE</strong><p>${esc(m.artifact)}</p></div><div class="label-sm">Run or inspect</div><pre>${esc(m.command)}</pre><div class="label-sm">Evidence that it works</div><p>${esc(m.verify)}</p><div class="example">“${esc(m.explain)}”</div><div class="evidence-note"><label class="field">Record your proof<textarea id="milestoneArtifact" placeholder="Paste a test result, describe a trace, or record the path to the artifact you built.">${esc(study.artifacts[m.id]||'')}</textarea><small>These are your notes, not an automated pass. Be ready to show and explain the artifact.</small></label></div><div class="step-footer"><button class="button" id="milestoneSource">Inspect the source →</button><button class="button primary" id="milestoneNext">${ui.milestone===9?'Open the capstone →':'Next milestone →'}</button></div></article></div>`}
function codeBody(){if(!codeManifest)return `<div class="empty-state">${codeLoadError?esc(codeLoadError):'Loading the tested source files…'}${codeLoadError?'<button class="button" id="retryCode">Retry</button>':''}</div>`;const f=codeManifest.files[ui.file];return `<div class="verified-panel"><b>${codeManifest.verification.total_checks} checks passed.</b> ${codeManifest.verification.offline_checks} offline, ${codeManifest.verification.mock_model_checks} mocked model, ${codeManifest.verification.real_integration_checks} real HTTP/MCP, and ${codeManifest.verification.mock_model_real_transport_checks} mock-model/real-transport bridge. Tested MCP ${esc(codeManifest.verification.mcp_sdk)}, protocol ${esc(codeManifest.verification.negotiated_protocol)}. Paid model calls were not made.</div><div class="code-layout" style="margin-top:22px"><div class="code-files">${codeManifest.files.map((x,i)=>`<button class="code-file ${i===ui.file?'active':''}" data-code-file="${i}">${esc(x.path)}<small>${esc(x.language)}</small></button>`).join('')}</div><div class="code-view"><h3>${esc(f.path)}</h3><p class="code-meta">${esc(f.purpose)}</p><div class="file-actions"><button class="button small" id="copySource">Copy file</button><button class="button small" id="downloadSource">Download file ↓</button></div><div class="search-box"><input type="search" id="codeSearch" value="${esc(ui.codeSearch)}" placeholder="Highlight a function, field, or error…" aria-label="Search within source"></div><div class="code-lines" id="codeLines" tabindex="0" aria-label="Source code with line numbers"></div></div></div><div class="callout yellow"><span class="hand">Explain the seam you are changing</span>Start at research_service.py for the business contract. api_server.py exposes HTTP. mcp_server.py wraps that API. live_mcp_agent.py adds a model-driven loop. Replacing the transport should preserve the evidence and authorization semantics.</div>`}
function runbookBody(){return `<div class="twocol"><div class="paper panel"><div class="hand">01 / get a clean environment</div><pre>python3 -m venv .venv\nsource .venv/bin/activate\npython -m pip install -r requirements-mcp.txt\npython eval_starter.py\npython eval_live_mock.py\npython eval_integrations.py\npython eval_bridge.py</pre><p class="tiny" style="margin-top:15px">Python3.11+ for the integration lab. On Windows, activate with <code>.venv\\Scripts\\activate</code>. Integration checks start and stop their own local services. Read README for complete prerequisites.</p></div><div class="paper panel"><div class="hand">02 / inspect both paths yourself</div><pre># Terminal A — localhost only\nexport DEMO_API_TOKEN="local-learning-token"\npython api_server.py\n\n# Terminal B — same environment\nexport DEMO_API_TOKEN="local-learning-token"\npython api_client.py --query "HubSpot"\npython mcp_client.py --query "HubSpot"</pre><p class="tiny" style="margin-top:15px">The token is a local teaching credential, not production identity. The MCP client starts a server subprocess; the HTTP server must be running for these manual commands.</p></div></div><div class="paper panel" style="margin-top:22px"><h3>03 / add the optional live model bridge</h3><pre>python -m pip install -r requirements-live.txt\n# Set ANTHROPIC_API_KEY and ANTHROPIC_MODEL through your environment.\n# Keep Terminal A running.\npython live_mcp_agent.py --query "Does SignalDesk support HubSpot and Salesforce?"</pre><p style="margin-top:15px">This path sends your question and fictional retrieved evidence to the configured model API and incurs usage charges. It is implemented and tested with a mock model plus real transports; a paid live call was not tested. The API key stays server-side. Choose a model supported by your account using current official documentation.</p></div><div class="section-head"><h2>What a production runbook must add.</h2></div><div class="paper panel"><table><thead><tr><th>Area</th><th>Decision to make</th><th>Verification</th></tr></thead><tbody><tr><td>Identity & tenant isolation</td><td>Trusted user identity, permission mapping, secret storage, revocation, audit access.</td><td>A cross-tenant query and a revoked cached document are blocked.</td></tr><tr><td>Durable execution</td><td>Run/action IDs, checkpoints, leases, retry budgets, timeouts, cancellation.</td><td>Crash between submission and response; reconcile the uncertain action.</td></tr><tr><td>Research freshness</td><td>Source registry, update cadence, effective dates, snapshots, deletions.</td><td>Old news and superseded pricing cannot silently become current findings.</td></tr><tr><td>Delivery & review</td><td>Artifact versions, approval scope, destination authorization, deduplication.</td><td>Changes after approval trigger revalidation; retries do not duplicate delivery.</td></tr><tr><td>Release & operations</td><td>Held-out evals, shadow runs, owner, alerts, pause, rollback, retention.</td><td>An operator can reconstruct a failure and revert a bad change.</td></tr></tbody></table></div><div class="callout yellow">The supplied code is a local teaching implementation. Remote MCP/OAuth, production tenant authentication, semantic retrieval, live web ingestion, and a deployed scheduler remain explicit implementation work.</div>`}
function buildPage(){return `${pageIntro('THE RUNNABLE CODE LAB','Build the capability. Change the interface.','A single research service is exposed through a direct HTTP API and an MCP adapter. Follow the source, run the tests, and add a bounded model loop.')}<div class="live-note">REAL LOCAL INTEGRATIONS · Fictional evidence · No private customer data · Live model access requires your own configured account</div><div class="tabs book-tabs">${[['milestones','10 build milestones'],['source','Source explorer'],['run','Setup & runbook']].map(([k,t])=>`<button class="tab ${ui.buildTab===k?'active':''}" data-build-tab="${k}">${t}</button>`).join('')}<a class="button small" href="research-agent-starter.zip" download>Download the complete kit ↓</a></div>${ui.buildTab==='milestones'?milestoneBody():ui.buildTab==='source'?codeBody():runbookBody()}`}
function loadCode(){if(codeManifest||codeLoading||codeLoadError)return;codeLoading=true;fetch('code-manifest.json').then(r=>{if(!r.ok)throw new Error('Could not load the source bundle. The ZIP remains available.');return r.json()}).then(d=>{codeManifest=d;codeLoading=false;if(section==='build'&&ui.buildTab==='source')render()}).catch(e=>{codeLoadError=e.message;codeLoading=false;if(section==='build'&&ui.buildTab==='source')render()})}
function paintCode(){if(!codeManifest||!$('#codeLines'))return;const f=codeManifest.files[ui.file],q=ui.codeSearch.toLowerCase();$('#codeLines').innerHTML=f.content.split('\n').map((line,i)=>`<div class="code-line ${q&&line.toLowerCase().includes(q)?'match':''}"><span class="ln">${i+1}</span><span>${esc(line)||' '}</span></div>`).join('')}
function saveDownload(name,text,type='text/plain'){const blob=new Blob([text],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Downloaded '+name)}

function debugPage(){const d=DEBUG_CASES[ui.debug],a=study.debug[d.id]||{};return `${pageIntro('THE DEBUGGING CLINIC','Find the failure before fixing the prompt.','Read the symptom and trace, form a diagnosis, then choose the next action. These are simulated incidents with explicit answer keys and regression tests.')}<div class="debug-grid"><div class="directory">${DEBUG_CASES.map((x,i)=>`<button class="${i===ui.debug?'active':''}" data-debug="${i}"><span>${String(i+1).padStart(2,'0')} · ${esc(x.title)}</span><small>${study.debug[x.id]?.checked?'•':''}</small></button>`).join('')}</div><article class="paper concept-main"><div class="eyebrow">${esc(d.tag)}</div><h2>${esc(d.title)}</h2><p class="definition">${esc(d.symptom)}</p><div class="label-sm">Inspect the trace · fictional incident</div><div class="debug-trace">${d.trace.map((t,i)=>`<div><span class="trace-no">${String(i+1).padStart(2,'0')}</span>${esc(t)}</div>`).join('')}</div><label class="field" style="margin-top:20px">Your diagnosis<textarea id="debugDiagnosis" placeholder="Which layer failed? What evidence points there? What would you inspect next?">${esc(a.diagnosis||'')}</textarea></label><h3>${esc(d.question)}</h3><div class="choice-list">${d.choices.map((c,i)=>`<label class="choice ${a.choice===i?'chosen':''}"><input type="radio" name="debugChoice" value="${i}" ${a.choice===i?'checked':''}>${esc(c)}</label>`).join('')}</div><button class="button primary" id="checkDebug" ${a.choice===undefined?'disabled':''}>Check the decision →</button><div id="debugFeedback">${ui.debugRevealed?debugFeedback(d,a):''}</div></article></div>`}
function debugFeedback(d,a){const right=a.choice===d.correct;return `<div class="feedback ${right?'':'wrong'}"><h3>${right?'That decision addresses the failure.':'Revisit the boundary that failed.'}</h3><p>${esc(d.why)}</p><p><b>Appropriate next action:</b> ${esc(d.choices[d.correct])}</p><div class="label-sm">Repair pattern · pseudocode</div><pre>${esc(d.fix)}</pre><div class="label-sm">Regression test to add</div><p>${esc(d.test)}</p><div class="label-sm">Explain your decision</div><p>“${esc(d.say)}”</p><p class="tiny">This checks a diagnosis against an authored answer key. Demonstrate the fix in code before claiming the engineering skill.</p></div>`}

function strategyPage(){const m=STRATEGY_MODULES[ui.strategy],ctx=STRATEGY_CONTEXT;return `${pageIntro('YOUR MONACO INTERVIEW NOTES','Think in systems. Design for an outcome.','Connect the harness, domain data, tools, long-running work, and business model. Each lesson turns one part of your notes into a decision you can defend.')}<div class="live-note">${esc(ctx.attribution)}</div><div class="course-layout"><div class="directory">${STRATEGY_MODULES.map((x,i)=>`<button data-strategy="${i}" class="${i===ui.strategy?'active':''}">${esc(x.title)}</button>`).join('')}</div><article class="paper concept-main"><div class="eyebrow">STRATEGY LESSON ${ui.strategy+1} OF ${STRATEGY_MODULES.length}</div><h2>${esc(m.title)}</h2><div class="strategy-note"><small class="note-source">FROM YOUR INTERVIEW NOTES</small><br>${esc(m.note)}</div>${paragraph(m.concept)}<div class="label-sm">Make it concrete</div>${paragraph(m.example)}<div class="label-sm">The decision to defend</div>${paragraph(m.decision)}<div class="whiteboard">${esc(m.whiteboard)}</div><div class="label-sm">A clear opening answer</div><div class="spoken-answer">${esc(m.explain30)}</div><details class="details"><summary>Go deeper: the technical explanation</summary><div>${paragraph(m.explain120)}</div></details>${m.followups.map(f=>`<details class="details"><summary>${esc(f.q)}</summary><div><div class="response-compare"><div class="weak"><b>WEAK ANSWER</b>${esc(f.weak)}</div><div class="strong"><b>STRONGER ANSWER</b>${esc(f.strong)}</div></div></div></details>`).join('')}<div class="step-output"><strong>YOUR EXERCISE</strong><p>${esc(m.exercise)}</p><strong>PRODUCE</strong><p>${esc(m.deliverable)}</p></div><button class="button primary" id="speakStrategy">Rehearse this answer →</button>${sourceLinks(m.sources)}</article></div><div class="section-head"><h2>What the public record supports.</h2><p>Public evidence and interview notes stay distinct.</p></div><div class="paper panel">${ctx.verifiedFacts?.length?ctx.verifiedFacts.map(f=>`<p>${esc(f.claim)} ${ext(f.url,f.title)}</p>`).join(''):'<p>The current guide uses Monaco’s public product description as context. The strategy modules are practice designs based on your notes.</p>'}${ctx.roadmapResolution?paragraph(ctx.roadmapResolution):''}${(ctx.unresolved||[]).map(x=>`<div class="roadmap-unresolved">${esc(x.text)}</div>`).join('')}<details class="details"><summary>${esc(ctx.proposedRoadmap.label)}</summary><div>${list(ctx.proposedRoadmap.parts)}</div></details></div><div class="section-head"><h2>Every note has a place.</h2><p>${NOTE_COVERAGE.length} explicit connections</p></div><div class="paper panel coverage-list">${NOTE_COVERAGE.map(n=>`<div class="coverage-item"><b>${esc(n.note)}</b>${esc(n.lesson)}<br><a href="#strategy" data-note-module="${esc(n.moduleId)}">Open the related lesson →</a></div>`).join('')}</div>`}

const economicsDefaults={large:{wins:10,acv:80000,margin:80,retention:80,acquisition:100000,onboarding:12000,cycle:6,hours:80},small:{wins:100,acv:8000,margin:70,retention:65,acquisition:80000,onboarding:500,cycle:1,hours:8}};
study.economics=study.economics||structuredClone(economicsDefaults);
function econFields(id,label,color){const v=study.economics[id];return `<div class="econ-card ${color}"><h3>${label}</h3><div class="econ-fields">${[['wins','Won accounts',1],['acv','Annual revenue / account ($)',1000],['margin','Gross margin (%)',1],['retention','Year-two renewal probability (%)',1],['acquisition','Acquisition + review cost ($)',1000],['onboarding','Onboarding cost / account ($)',100],['cycle','Sales-cycle delay (months)',1],['hours','Onboarding hours / account',1]].map(([k,t,step])=>`<label class="field">${t}<input type="number" min="0" ${['margin','retention'].includes(k)?'max="100"':''} step="${step}" data-econ="${id}.${k}" value="${v[k]}"></label>`).join('')}</div></div>`}
function econMath(v){const year1=v.wins*v.acv*v.margin/100,year2=year1*v.retention/100,contribution=year1+year2-v.acquisition-v.wins*v.onboarding;return {year1,year2,contribution,hours:v.wins*v.hours,renewed:v.wins*v.retention/100,concentration:v.wins?100/v.wins:0}}
function outcomesPage(){return `${pageIntro('MEASURE WHAT THE SYSTEM ACHIEVES','Ten big deals. A hundred small ones. Which is better?','Make the comparison explicit. Deal count, throughput, revenue, margin, retention, review effort, and time can point in different directions.')}<div class="live-note">ILLUSTRATIVE SCENARIO · Invented inputs · Two full service years after acquisition · No guarantee about Monaco or any real business</div><div class="economics">${econFields('large','A / a few larger customers','blue')}${econFields('small','B / many smaller customers','mint')}</div><div id="econResults"></div><div class="callout yellow"><span class="hand">Keep the clock honest</span>This model measures two full service years, not the next24 calendar months. Sales-cycle delay is shown separately. For a cash-planning decision, model when deals actually close and when revenue and costs arrive. Do not compare immature cohorts with fully observed ones.</div><details class="details"><summary>Inspect the formula and assumptions</summary><div><pre>Year 1 gross profit = wins × annual revenue/account × gross margin\nExpected year 2 gross profit = year 1 gross profit × renewal probability\nContribution = year 1 GP + expected year 2 GP\n             − incremental acquisition/review cost\n             − wins × onboarding cost/account</pre><p>Assumes equal account sizes inside each cohort and unchanged pricing/margin. Excludes expansion, contraction, discounting, taxes, shared fixed costs, and partial-year timing. Onboarding is an incremental cost only if it is not already included in gross margin. Probability-weighted renewals are an expectation, not a promise.</p></div></details><div class="section-head"><h2>Capture outcomes when they become meaningful.</h2></div><div class="paper panel table-scroll"><table><thead><tr><th>Stage</th><th>Event to capture</th><th>What it can establish</th></tr></thead><tbody><tr><td>Research complete</td><td>task_id, account_id, evidence version, latency, tool cost, gaps</td><td>Execution and evidence quality; not revenue.</td></tr><tr><td>Rep accepts or edits</td><td>artifact version, accepted/rejected, reason, edit/review minutes</td><td>Usefulness and actual human work saved.</td></tr><tr><td>Qualified opportunity</td><td>definition met, opportunity_id, cohort, source workflow</td><td>Pipeline quality, with downstream validation still pending.</td></tr><tr><td>Deal closes</td><td>contract value, margin assumptions, acquisition effort, close date</td><td>Won revenue and cost; link to the original cohort without assuming causality.</td></tr><tr><td>Activation and renewal</td><td>time-to-value, realized use, support load, expansion/contraction, churn reason</td><td>Whether the acquired customer became durable value.</td></tr></tbody></table></div><div class="section-head"><h2>A scorecard with separate layers.</h2></div><div class="metric-definition">${[['Evidence quality','Supported claims / reviewed claims. Inspect relevance, date, and citation entailment.'],['Task throughput','Accepted tasks per unit time at the target quality. Include reviewer and tool bottlenecks.'],['Human effort','Net time saved after review, corrections, escalations, and operating effort.'],['Commercial outcome','Qualified opportunities, won revenue, and contribution by comparable cohort.'],['Retention and fit','Activation, realized product use, renewal, churn, and reasons for poor fit.'],['System reliability','Completion, errors, duplicates, recovery, latency, cost, and permission violations.']].map(([h,p])=>`<article><h3>${h}</h3><p>${p}</p></article>`).join('')}</div><div class="whiteboard" style="margin-top:22px">Inputs → useful research → accepted action → qualified opportunity → won revenue → activated customer → renewal\n                  ↖ review, failure, and churn reasons feed the next version ↲</div><div class="callout mint"><span class="hand">Explain the decision</span>“I’d optimize for durable contribution and customer value, with quality and capacity constraints. Ten larger wins may be better, but slower sales cycles, implementation load, concentration, and churn could reverse that choice. I’d compare matched cohorts and capture outcomes at the stage where they become observable.”</div><div class="paper panel"><h3>Design the experiment before claiming impact.</h3><p>Define eligibility and success first. Where feasible, randomize comparable accounts or teams to the existing process and the new workflow. Keep the observation window long enough for the outcome, record treatment exposure, and inspect review effort and failure costs. If randomization is unavailable, state the limitations of the comparison rather than treating before/after movement as proof.</p><p><b>Try:</b> lower larger-customer renewal, increase onboarding effort, or reverse annual values. Explain which assumption changes your recommendation and what data you would collect next.</p></div>`}
function paintEconomics(){const a=study.economics.large,b=study.economics.small,x=econMath(a),y=econMath(b),usd=n=>n.toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0});$('#econResults').innerHTML=`<div class="econ-results"><div><small>A / TWO-YEAR EXPECTED CONTRIBUTION</small><strong>${usd(x.contribution)}</strong><small>${usd(x.year1)} first-year GP + ${usd(x.year2)} expected second-year GP</small></div><div><small>B / TWO-YEAR EXPECTED CONTRIBUTION</small><strong>${usd(y.contribution)}</strong><small>${usd(y.year1)} first-year GP + ${usd(y.year2)} expected second-year GP</small></div></div><div class="paper panel"><table><thead><tr><th>Constraint or risk</th><th>A / larger customers</th><th>B / smaller customers</th></tr></thead><tbody><tr><td>Sales-cycle delay</td><td>${a.cycle} months</td><td>${b.cycle} months</td></tr><tr><td>Onboarding capacity required</td><td>${x.hours.toLocaleString()} hours</td><td>${y.hours.toLocaleString()} hours</td></tr><tr><td>Expected renewed accounts</td><td>${x.renewed.toFixed(1)}</td><td>${y.renewed.toFixed(1)}</td></tr><tr><td>Share of first-year revenue per equal-size account</td><td>${x.concentration.toFixed(1)}%</td><td>${y.concentration.toFixed(1)}%</td></tr></tbody></table><p class="tiny muted" style="margin-top:15px">Under these inputs, ${x.contribution===y.contribution?'both have equal modeled contribution':x.contribution>y.contribution?'A has higher modeled contribution':'B has higher modeled contribution'}. This does not resolve timing, capacity, concentration, or product-strategy tradeoffs.</p></div>`}

function interviewTopic(){return ui.interviewMode==='concept'?DEEP_CONCEPTS[ui.interviewItem]:STRATEGY_MODULES[ui.interviewItem]}
function interviewPage(){const t=interviewTopic(),topics=ui.interviewMode==='concept'?DEEP_CONCEPTS:STRATEGY_MODULES,id=ui.interviewMode+':'+t.id;return `${pageIntro('EXPLAIN YOUR DECISIONS','Be clear enough to be questioned.','Practice a short explanation, a technical walkthrough, and a tradeoff. Then answer a skeptical follow-up without hiding behind terminology.')}<div class="interview-switch"><label class="field">Practice area<select id="interviewMode"><option value="concept" ${ui.interviewMode==='concept'?'selected':''}>Technical concepts</option><option value="strategy" ${ui.interviewMode==='strategy'?'selected':''}>Your Monaco interview notes</option></select></label><label class="field">Topic<select id="interviewTopic">${topics.map((x,i)=>`<option value="${i}" ${ui.interviewItem===i?'selected':''}>${esc(x.term||x.title)}</option>`).join('')}</select></label></div><div class="speaking-room"><div class="eyebrow">SAY IT IN YOUR OWN WORDS</div><h2>${esc(t.term||t.title)}</h2><p>${esc(ui.interviewMode==='concept'?t.question:t.exercise)}</p><div class="interview-timer"><span class="timer-digits" id="timerDigits">${formatTime(ui.timerSeconds)}</span><button class="button small" id="timerStart">${ui.timerRunning?'Pause':'Start timer'}</button><button class="button small" data-timer="30">30 seconds</button><button class="button small" data-timer="120">2 minutes</button></div><label class="field">Your explanation<textarea id="speakingNotes" style="min-height:145px" placeholder="Define it. Trace an example. Name the tradeoff. Explain how you would test it.">${esc(study.speaking[id]||'')}</textarea><small>Notes stay on this device. The timer does not record audio or grade your answer.</small></label></div><div class="answer-tabs">${[['30','30-second example'],['120','Technical walkthrough'],['followup','Skeptical follow-up'],['whiteboard','Whiteboard structure']].map(([k,label])=>`<button data-answer-tab="${k}" class="${ui.speakingTab===k?'active':''}">${label}</button>`).join('')}</div><div id="spokenPanel">${spokenPanel(t)}</div><div class="section-head"><h2>Turn a choice into a defensible decision.</h2></div><div class="paper panel"><div class="twocol">${[['choice','I would choose…','One bounded research agent'],['reason','Because the requirement is…','The next useful search depends on the evidence'],['tradeoff','The tradeoff is…','More latency and operational complexity'],['measure','I would validate it with…','Held-out task quality, review time, and cost']].map(([key,label,placeholder])=>`<label class="field">${label}<input data-decision="${key}" placeholder="${placeholder}" value="${esc(study.decision[key]||'')}"></label>`).join('')}</div><div class="example" id="decisionSentence"></div></div><div class="callout yellow"><span class="hand">Listen for these warning signs in your own answer</span>“The model handles it” without an execution boundary. “RAG prevents hallucinations” without support checks. “MCP gives full access” without authorization. “More leads” without qualified outcomes. “Fully autonomous” without recovery and ownership.</div>`}
function spokenPanel(t){if(ui.speakingTab==='30')return `<div class="spoken-answer">${esc(t.explain30)}</div>`;if(ui.speakingTab==='120')return `<div class="spoken-answer technical">${esc(t.explain120)}</div>`;if(ui.speakingTab==='whiteboard')return `<div class="whiteboard">${esc(t.whiteboard||`1. Place ${t.term} in the system.\n2. Draw the input, contract, execution, and output.\n3. Mark identity, permissions, and the trust boundary.\n4. Show one failure and how you observe or recover from it.\n5. Name the requirement and the test that justify this choice.`)}</div>`;const followups=t.followups||[{q:t.followup,strong:t.strong,weak:t.weak}];return followups.map(f=>`<div class="paper panel" style="margin-bottom:15px"><h3>${esc(f.q)}</h3><div class="response-compare"><div class="weak"><b>WEAK ANSWER</b>${esc(f.weak||'Restating the desired outcome without describing a mechanism or test.')}</div><div class="strong"><b>STRONGER ANSWER</b>${esc(f.strong)}</div></div></div>`).join('')}
function formatTime(n){return `${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`}
function stopTimer(){clearInterval(timerHandle);timerHandle=null;ui.timerRunning=false}
function paintDecision(){const d=study.decision;$('#decisionSentence').textContent=`I would choose ${d.choice||'[an approach]'} because ${d.reason||'[the requirement]'}. The tradeoff is ${d.tradeoff||'[a cost or limitation]'}. I would validate that choice with ${d.measure||'[evidence and a test]'}.`}

function masteryPage(){const c=CAPSTONES[ui.capstone],s=study.capstones[c.id]||{answer:'',scores:{}};const concepts=Object.values(study.concepts).filter(x=>x.level==='applied'&&x.evidence?.trim()).length,artifacts=Object.values(study.artifacts).filter(x=>x.trim()).length,diagnoses=Object.values(study.debug).filter(x=>x.checked).length;return `${pageIntro('PROVE YOUR UNDERSTANDING','Produce evidence of the skill.','A course checklist shows progress. Mastery requires an artifact you can run, a failure you can diagnose, and decisions you can defend under questioning.')}<div class="mastery-progress"><div><strong>${concepts}</strong><p>Concepts with a self-reported application and evidence note</p></div><div><strong>${artifacts}/10</strong><p>Build milestones with an artifact note</p></div><div><strong>${diagnoses}/12</strong><p>Debugging decisions checked against the authored key</p></div></div><div class="live-note" style="margin-top:18px">These are activity indicators, not an automated certification. Review the artifacts and explanations to assess actual competence.</div><div class="section-head"><h2>Take an unfamiliar case.</h2><button class="button small" id="exportPortfolio">Export my learning portfolio ↓</button></div><div class="tabs">${CAPSTONES.map((x,i)=>`<button class="tab ${i===ui.capstone?'active':''}" data-capstone="${i}">Case ${i+1}</button>`).join('')}</div><div class="paper panel"><div class="eyebrow">HYPOTHETICAL LIVE CASE</div><h2>${esc(c.title)}</h2><p>${esc(c.brief)}</p><p class="tiny muted">${esc(c.timebox)}</p><div class="twocol"><div><h3>Constraints</h3>${list(c.constraints)}</div><div><h3>What you must produce</h3>${list(c.deliverables)}</div></div><label class="field capstone-answer">Your discovery questions, architecture, implementation plan, tests, and recommendation<textarea id="capstoneAnswer" placeholder="State assumptions. Trace one task. Name failure behavior. Specify evidence and metrics. Explain what changes your mind.">${esc(s.answer||'')}</textarea></label></div><div class="twocol" style="margin-top:22px"><div class="paper panel"><h3>Self-assessment rubric</h3><p>0: absent · 1: named · 2: explained · 3: supported by a concrete design · 4: demonstrated with a test or artifact.</p><div class="assessment-rubric">${c.rubric.map((r,i)=>`<label><div><b>${esc(r.label)} · ${r.points} points</b><p>${esc(r.criteria)}</p></div><select data-rubric-score="${i}" aria-label="Score ${esc(r.label)}">${[0,1,2,3,4].map(v=>`<option value="${v}" ${Number(s.scores?.[i]||0)===v?'selected':''}>${v} / 4</option>`).join('')}</select></label>`).join('')}</div><div class="row" style="margin-top:20px"><span class="tiny muted">Self-assessed coverage and evidence</span><span class="score" id="masteryScore"></span></div><div id="remediation"></div></div><div><div class="paper panel"><h3>Compare after your attempt</h3><details class="details"><summary>Reveal one defensible answer</summary><div>${paragraph(c.answer)}</div></details>${c.followups.map(f=>`<details class="details"><summary>${esc(f.q)}</summary><div>${paragraph(f.strong)}</div></details>`).join('')}</div><div class="callout mint"><span class="hand">Your final demonstration</span>Run the integration. Show the evidence returned. Trigger a failure and explain the response. Change a requirement and justify the architectural consequence. Connect the accepted output to a measurable customer outcome.</div></div></div>`}
function paintMastery(){const c=CAPSTONES[ui.capstone],s=study.capstones[c.id]||{scores:{}};const score=c.rubric.reduce((a,r,i)=>a+r.points*Number(s.scores?.[i]||0)/4,0);$('#masteryScore').textContent=score.toFixed(0)+'/100';const gaps=c.rubric.filter((r,i)=>Number(s.scores?.[i]||0)<3);$('#remediation').innerHTML=gaps.length?`<div class="label-sm">What to strengthen next</div>${list(gaps.map(r=>r.label+': '+r.criteria))}`:'<div class="callout mint">Now have another person probe your assumptions and inspect the artifacts. A self-score is not independent validation.</div>'}
function exportPortfolio(){saveDownload('research-agent-learning-portfolio.json',JSON.stringify({guide:'Research Agent Fieldguide',exported_at:new Date().toISOString(),note:'Self-reported learning evidence; not a certification or automated evaluation.',study:state.study,original_build_checklist:state.done},null,2),'application/json')}

window.GUIDE_EXTENSIONS={pages:{concepts:{title:'Understand the terms',render:conceptsPage},protocol:{title:'APIs & MCP, unfolded',render:protocolPage},build:{title:'Runnable code lab',render:buildPage},debug:{title:'Debugging clinic',render:debugPage},strategy:{title:'Vertical harness strategy',render:strategyPage},outcomes:{title:'Measure real outcomes',render:outcomesPage},interview:{title:'Explain your decisions',render:interviewPage},mastery:{title:'Prove your understanding',render:masteryPage}},bind:bindUpgrade};
function bindUpgrade(route){if(route!=='interview')stopTimer();if(route==='concepts'){paintConceptDirectory();$('#conceptSearch').oninput=e=>{ui.search=e.target.value;paintConceptDirectory()};$('#conceptCategory').onchange=e=>{ui.category=e.target.value;paintConceptDirectory()};$('#conceptLevel').onchange=e=>{const c=DEEP_CONCEPTS[ui.concept];study.concepts[c.id]={...storedConcept(c),level:e.target.value};persist()};$('#conceptEvidence').oninput=e=>{const c=DEEP_CONCEPTS[ui.concept];study.concepts[c.id]={...storedConcept(c),evidence:e.target.value};persist()};$('#conceptSpeak').onclick=()=>{ui.interviewMode='concept';ui.interviewItem=ui.concept;location.hash='interview'}}
 if(BLUEPRINTS[route]){document.querySelectorAll('[data-blueprint-mode]').forEach(b=>b.onclick=()=>{ui.blueprintModes[route]=b.dataset.blueprintMode;render()});document.querySelectorAll('[data-usecase-node]').forEach(b=>b.onclick=()=>{ui.blueprintNodes[route]=Number(b.dataset.usecaseNode);document.querySelectorAll('[data-usecase-node]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});$('#usecaseDetail').innerHTML=usecaseDetail(route)});if($('#copyWorkflowSchema'))$('#copyWorkflowSchema').onclick=()=>copy(textValue(USECASE_DEPTH[route].schema))}
 if(route==='protocol'){document.querySelectorAll('[data-protocol]').forEach(b=>b.onclick=()=>{ui.protocol=b.dataset.protocol;ui.phase=0;render()});document.querySelectorAll('[data-phase]').forEach(b=>b.onclick=()=>{ui.phase=Number(b.dataset.phase);render()});$('#phasePrev').onclick=()=>{ui.phase--;render()};$('#phaseNext').onclick=()=>{ui.phase++;render()}}
 if(route==='build'){document.querySelectorAll('[data-build-tab]').forEach(b=>b.onclick=()=>{ui.buildTab=b.dataset.buildTab;render()});if(ui.buildTab==='milestones'){document.querySelectorAll('[data-milestone]').forEach(b=>b.onclick=()=>{ui.milestone=Number(b.dataset.milestone);render()});$('#milestoneArtifact').oninput=e=>{study.artifacts[BUILD_MILESTONES[ui.milestone].id]=e.target.value;persist()};$('#milestoneSource').onclick=()=>{ui.buildTab='source';render()};$('#milestoneNext').onclick=()=>{if(ui.milestone===9)location.hash='mastery';else{ui.milestone++;render()}}}else if(ui.buildTab==='source'){loadCode();if(codeManifest){paintCode();document.querySelectorAll('[data-code-file]').forEach(b=>b.onclick=()=>{ui.file=Number(b.dataset.codeFile);ui.codeSearch='';render()});$('#codeSearch').oninput=e=>{ui.codeSearch=e.target.value;paintCode()};$('#copySource').onclick=()=>copy(codeManifest.files[ui.file].content);$('#downloadSource').onclick=()=>saveDownload(codeManifest.files[ui.file].path,codeManifest.files[ui.file].content)}if($('#retryCode'))$('#retryCode').onclick=()=>{codeLoadError='';loadCode()}}}
 if(route==='debug'){document.querySelectorAll('[data-debug]').forEach(b=>b.onclick=()=>{ui.debug=Number(b.dataset.debug);ui.debugRevealed=false;render()});const d=DEBUG_CASES[ui.debug];$('#debugDiagnosis').oninput=e=>{study.debug[d.id]={...study.debug[d.id],diagnosis:e.target.value};persist()};document.querySelectorAll('[name="debugChoice"]').forEach(el=>el.onchange=()=>{study.debug[d.id]={...study.debug[d.id],choice:Number(el.value),checked:false};persist();ui.debugRevealed=false;$('#checkDebug').disabled=false;$('#debugFeedback').innerHTML='';document.querySelectorAll('.choice').forEach(c=>c.classList.toggle('chosen',c.contains(el)))});$('#checkDebug').onclick=()=>{study.debug[d.id].checked=true;study.debug[d.id].correct=study.debug[d.id].choice===d.correct;persist();ui.debugRevealed=true;$('#debugFeedback').innerHTML=debugFeedback(d,study.debug[d.id])}}
 if(route==='strategy'){document.querySelectorAll('[data-strategy]').forEach(b=>b.onclick=()=>{ui.strategy=Number(b.dataset.strategy);render()});document.querySelectorAll('[data-note-module]').forEach(a=>a.onclick=e=>{e.preventDefault();ui.strategy=STRATEGY_MODULES.findIndex(m=>m.id===a.dataset.noteModule);render();$('#main').scrollIntoView()});$('#speakStrategy').onclick=()=>{ui.interviewMode='strategy';ui.interviewItem=ui.strategy;location.hash='interview'}}
 if(route==='outcomes'){paintEconomics();document.querySelectorAll('[data-econ]').forEach(el=>el.oninput=()=>{const [group,key]=el.dataset.econ.split('.');let v=Math.max(0,Number(el.value)||0);if(['margin','retention'].includes(key))v=Math.min(100,v);if(key==='wins')v=Math.floor(v);study.economics[group][key]=v;persist();paintEconomics()})}
 if(route==='interview'){paintDecision();$('#interviewMode').onchange=e=>{stopTimer();ui.interviewMode=e.target.value;ui.interviewItem=0;render()};$('#interviewTopic').onchange=e=>{stopTimer();ui.interviewItem=Number(e.target.value);render()};$('#speakingNotes').oninput=e=>{study.speaking[ui.interviewMode+':'+interviewTopic().id]=e.target.value;persist()};document.querySelectorAll('[data-answer-tab]').forEach(b=>b.onclick=()=>{ui.speakingTab=b.dataset.answerTab;document.querySelectorAll('[data-answer-tab]').forEach(x=>x.classList.toggle('active',x===b));$('#spokenPanel').innerHTML=spokenPanel(interviewTopic())});document.querySelectorAll('[data-timer]').forEach(b=>b.onclick=()=>{stopTimer();ui.timerSeconds=Number(b.dataset.timer);$('#timerDigits').textContent=formatTime(ui.timerSeconds);$('#timerStart').textContent='Start timer'});$('#timerStart').onclick=()=>{if(ui.timerRunning){stopTimer();$('#timerStart').textContent='Resume';return}if(ui.timerSeconds===0)ui.timerSeconds=120;ui.timerRunning=true;$('#timerStart').textContent='Pause';timerHandle=setInterval(()=>{ui.timerSeconds=Math.max(0,ui.timerSeconds-1);if($('#timerDigits'))$('#timerDigits').textContent=formatTime(ui.timerSeconds);if(ui.timerSeconds===0){stopTimer();if($('#timerStart'))$('#timerStart').textContent='Restart';toast('Time. State your recommendation and one uncertainty.')}},1000)};document.querySelectorAll('[data-decision]').forEach(el=>el.oninput=()=>{study.decision[el.dataset.decision]=el.value;persist();paintDecision()})}
 if(route==='mastery'){paintMastery();document.querySelectorAll('[data-capstone]').forEach(b=>b.onclick=()=>{ui.capstone=Number(b.dataset.capstone);render()});const id=CAPSTONES[ui.capstone].id;$('#capstoneAnswer').oninput=e=>{study.capstones[id]={...study.capstones[id],answer:e.target.value};persist()};document.querySelectorAll('[data-rubric-score]').forEach(el=>el.onchange=()=>{const c=study.capstones[id]||{answer:'',scores:{}};c.scores={...c.scores,[el.dataset.rubricScore]:Number(el.value)};study.capstones[id]=c;persist();paintMastery()});$('#exportPortfolio').onclick=exportPortfolio}
 if(route==='kit'){const note=document.createElement('div');note.className='upgrade-note';note.innerHTML='<h3>The expanded implementation is in the Code lab.</h3><p>Run the direct HTTP API, real MCP client/server, and optional model → MCP → HTTP bridge. <a href="#build">Open setup, source, and verification →</a></p>';$('#main').prepend(note)}
}
$('#mobileJump').innerHTML=[...document.querySelectorAll('[data-nav]')].map(a=>`<option value="${a.dataset.nav}">${esc(a.textContent.trim())}</option>`).join('');$('#mobileJump').onchange=e=>{location.hash=e.target.value};
