BUILD_MILESTONES.find(m=>m.id==='api').command='export DEMO_API_TOKEN="local-learning-token"\npython api_server.py\n# In a second terminal, set the same token:\npython api_client.py --query "HubSpot"';
BUILD_MILESTONES.find(m=>m.id==='mcp').command='python -m pip install -r requirements-mcp.txt\n# With the HTTP server running and token configured:\npython mcp_client.py --query "HubSpot"\n# Or run the self-contained integration checks:\npython eval_integrations.py';
render();
